bool elapsed(uint32_t now,uint32_t since,uint32_t duration){return uint32_t(now-since)>=duration;}
void setText(char* dst,size_t cap,const char* value){strlcpy(dst,value?value:"",cap);}
const char* diagText(Diag value){switch(value){case Diag::Idle:return "Non lance";case Diag::Running:return "En cours";case Diag::ResetReceived:return "Reponse recue";case Diag::Absent:return "NanoBCU non detecte";case Diag::ProtocolError:return "Erreur de protocole";case Diag::BusMonitor:return "Bus monitor passif";case Diag::TunnelNormal:return "Mode normal tunnel";}return "Inconnu";}
const char* diagText(){return diagText(diag);}
const char* wifiReason(uint8_t r){switch(r){case 2:return "AUTH_EXPIRE";case 3:return "AUTH_LEAVE";case 4:return "ASSOC_EXPIRE";case 8:return "ASSOC_LEAVE";case 15:return "4WAY_HANDSHAKE_TIMEOUT";case 36:return "STA_LEAVING";case 39:return "TIMEOUT";case 200:return "BEACON_TIMEOUT";case 201:return "NO_AP_FOUND";case 202:return "AUTH_FAIL";case 203:return "ASSOC_FAIL";case 204:return "HANDSHAKE_TIMEOUT";case 205:return "CONNECTION_FAIL";case 207:return "ROAMING";default:return "AUTRE";}}
const char* wifiPsName(wifi_ps_type_t value){switch(value){case WIFI_PS_NONE:return "WIFI_PS_NONE";case WIFI_PS_MIN_MODEM:return "WIFI_PS_MIN_MODEM";case WIFI_PS_MAX_MODEM:return "WIFI_PS_MAX_MODEM";default:return "INCONNU";}}
void wifiEvent(WiFiEvent_t event,WiFiEventInfo_t info){uint32_t now=millis();if(event==ARDUINO_EVENT_WIFI_STA_CONNECTED){wifiAssociatedAt=now;wifiLastChannel=info.wifi_sta_connected.channel;memcpy(wifiLastBssid,info.wifi_sta_connected.bssid,6);++wifiAssociations;Serial.printf("[WIFI-DIAG] associe t=%lu ms canal=%u BSSID=%02X:%02X:%02X:%02X:%02X:%02X depuis_deconnexion=%lu ms\n",now,unsigned(wifiLastChannel),wifiLastBssid[0],wifiLastBssid[1],wifiLastBssid[2],wifiLastBssid[3],wifiLastBssid[4],wifiLastBssid[5],wifiLastDisconnectAt?now-wifiLastDisconnectAt:now);}else if(event==ARDUINO_EVENT_WIFI_STA_GOT_IP){wifiGotIpAt=now;++wifiGotIps;Serial.printf("[WIFI-DIAG] DHCP t=%lu ms delai_apres_association=%lu ms IP=%s RSSI=%ld dBm\n",now,wifiAssociatedAt?now-wifiAssociatedAt:0,WiFi.localIP().toString().c_str(),long(WiFi.RSSI()));}else if(event==ARDUINO_EVENT_WIFI_STA_DISCONNECTED){wifiLastDisconnectAt=now;wifiLastReason=info.wifi_sta_disconnected.reason;memcpy(wifiLastBssid,info.wifi_sta_disconnected.bssid,6);++wifiDisconnects;Serial.printf("[WIFI-DIAG] deconnexion t=%lu ms motif=%u (%s) BSSID=%02X:%02X:%02X:%02X:%02X:%02X RSSI_avant=%ld dBm\n",now,unsigned(wifiLastReason),wifiReason(wifiLastReason),wifiLastBssid[0],wifiLastBssid[1],wifiLastBssid[2],wifiLastBssid[3],wifiLastBssid[4],wifiLastBssid[5],long(wifiRssiLast));}else if(event==ARDUINO_EVENT_WIFI_STA_LOST_IP)Serial.printf("[WIFI-DIAG] perte IP t=%lu ms\n",now);}
#if KNX_NETWORK_TRANSPORT == KNX_TRANSPORT_ETHERNET
void networkEvent(WiFiEvent_t event,WiFiEventInfo_t info){
 wifiEvent(event,info);
 if(event==ARDUINO_EVENT_ETH_CONNECTED){ethernetLink=true;Serial.println(F("[ETH] lien actif"));}
 else if(event==ARDUINO_EVENT_ETH_GOT_IP){ethernetHasIp=true;++ethernetGotIps;++networkGeneration;Serial.printf("[ETH] DHCP IP=%s debit=%u Mbps duplex=%s\n",ETH.localIP().toString().c_str(),unsigned(ETH.linkSpeed()),ETH.fullDuplex()?"full":"half");}
 else if(event==ARDUINO_EVENT_ETH_DISCONNECTED){ethernetLink=false;ethernetHasIp=false;++ethernetDisconnects;++networkGeneration;Serial.println(F("[ETH] lien perdu"));}
 else if(event==ARDUINO_EVENT_ETH_STOP){ethernetLink=false;ethernetHasIp=false;++networkGeneration;Serial.println(F("[ETH] interface arretee"));}
}
#endif
void formatPa(uint16_t a,char* out,size_t cap){snprintf(out,cap,"%u.%u.%u",(a>>12)&15,(a>>8)&15,a&255);}
bool parsePa(const char* s,bool& configured,uint16_t& out){configured=false;out=0;if(!s||!*s)return true;unsigned a,l,d;char x;if(sscanf(s,"%u.%u.%u%c",&a,&l,&d,&x)!=3||a>15||l>15||d>255)return false;configured=true;out=(a<<12)|(l<<8)|d;return true;}
void formatIp(uint32_t a,char* out,size_t cap){snprintf(out,cap,"%u.%u.%u.%u",(a>>24)&255,(a>>16)&255,(a>>8)&255,a&255);}
bool parseIp(const char* s,uint32_t& out){unsigned a,b,c,d;char x;if(!s||sscanf(s,"%u.%u.%u.%u%c",&a,&b,&c,&d,&x)!=4||a<224||a>239||b>255||c>255||d>255)return false;out=(a<<24)|(b<<16)|(c<<8)|d;return true;}
bool parseUInt(const char* s,uint32_t lo,uint32_t hi,uint32_t& out){if(!s||!*s)return false;char* e=nullptr;unsigned long v=strtoul(s,&e,10);if(!e||*e||v<lo||v>hi)return false;out=v;return true;}
bool validIndividualAddress(uint16_t address,bool tunnelAddress){if(!address||address==0xFFFF)return false;const uint8_t area=address>>12,line=(address>>8)&15,device=address&255;if(area>15||line>15)return false;if(tunnelAddress&&device==0)return false;return true;}
uint8_t configuredTunnelCount(const RouterConfig& c){uint8_t count=0;for(uint16_t address:c.tunnelAddresses)if(address)++count;return count;}
bool validTunnelAddresses(const RouterConfig& c){for(uint8_t i=0;i<kTunnelSlots;++i){const uint16_t address=c.tunnelAddresses[i];if(!address)continue;if(!validIndividualAddress(address,true)||(c.paSet&&address==c.pa))return false;for(uint8_t j=0;j<i;++j)if(address==c.tunnelAddresses[j])return false;}return true;}
bool commissioningReady(const RouterConfig& c){return c.paSet&&validIndividualAddress(c.pa,false)&&configuredTunnelCount(c)>0&&validTunnelAddresses(c);}
bool valid(const RouterConfig& c){uint8_t first=c.multicast>>24;return c.version==kConfigVersion&&(!c.paSet||validIndividualAddress(c.pa,false))&&first>=224&&first<=239&&c.port&&c.timeoutMs>=3000&&c.timeoutMs<=60000&&c.probeMs>=500&&c.probeMs<=10000&&c.probeMs<c.timeoutMs&&c.groupStart<=c.groupEnd&&validTunnelAddresses(c);}
bool loadConfig(){struct LegacyConfigV1{uint16_t version;bool paSet;uint16_t pa;uint32_t multicast;uint16_t port;uint32_t timeoutMs,probeMs;};struct LegacyConfigV2{uint16_t version;bool paSet;uint16_t pa;uint32_t multicast;uint16_t port;uint32_t timeoutMs,probeMs;bool routeIpToTp,routeTpToIp,allowGroup,allowIndividual;uint16_t groupStart,groupEnd;};struct LegacyConfigV3{uint16_t version;bool paSet;uint16_t pa;uint32_t multicast;uint16_t port;uint32_t timeoutMs,probeMs;bool routeIpToTp,routeTpToIp,allowGroup,allowIndividual;uint16_t groupStart,groupEnd;uint16_t tunnelAddresses[kTunnelSlots];};if(!prefs.begin(kNvs,true))return false;const size_t stored=prefs.getBytesLength("config");RouterConfig candidate;size_t n=0;if(stored==sizeof(candidate))n=prefs.getBytes("config",&candidate,sizeof(candidate));else if(stored==sizeof(LegacyConfigV3)){LegacyConfigV3 old{};if(prefs.getBytes("config",&old,sizeof(old))==sizeof(old)&&old.version==3){candidate.paSet=old.paSet;candidate.pa=old.pa;candidate.multicast=old.multicast;candidate.port=old.port;candidate.timeoutMs=old.timeoutMs;candidate.probeMs=old.probeMs;candidate.routeIpToTp=old.routeIpToTp;candidate.routeTpToIp=old.routeTpToIp;candidate.allowGroup=old.allowGroup;candidate.allowIndividual=old.allowIndividual;candidate.groupStart=old.groupStart;candidate.groupEnd=old.groupEnd;memcpy(candidate.tunnelAddresses,old.tunnelAddresses,sizeof(candidate.tunnelAddresses));n=sizeof(candidate);}}else if(stored==sizeof(LegacyConfigV1)){LegacyConfigV1 old{};if(prefs.getBytes("config",&old,sizeof(old))==sizeof(old)&&old.version==1){candidate.paSet=old.paSet;candidate.pa=old.pa;candidate.multicast=old.multicast;candidate.port=old.port;candidate.timeoutMs=old.timeoutMs;candidate.probeMs=old.probeMs;n=sizeof(candidate);}}else if(stored==sizeof(LegacyConfigV2)){LegacyConfigV2 old{};if(prefs.getBytes("config",&old,sizeof(old))==sizeof(old)&&old.version==2){candidate.paSet=old.paSet;candidate.pa=old.pa;candidate.multicast=old.multicast;candidate.port=old.port;candidate.timeoutMs=old.timeoutMs;candidate.probeMs=old.probeMs;candidate.routeIpToTp=old.routeIpToTp;candidate.routeTpToIp=old.routeTpIp;candidate.allowGroup=old.allowGroup;candidate.allowIndividual=old.allowIndividual;candidate.groupStart=old.groupStart;candidate.groupEnd=old.groupEnd;n=sizeof(candidate);}}prefs.end();if(n!=sizeof(candidate)||!valid(candidate))return false;config=candidate;return true;}
bool saveConfig(const RouterConfig& c){if(!valid(c)||!prefs.begin(kNvs,false))return false;size_t n=prefs.putBytes("config",&c,sizeof(c));prefs.end();return n==sizeof(c);}
