void addIpLog(IPAddress remote,uint16_t port,CemiFrame& cemi,const uint8_t* raw,size_t rawLen){if(ipDisplayPaused){++ipLogLosses;return;}if(ipLogCount==kLogEntries)++ipLogLosses;else ++ipLogCount;IpLogEntry& e=ipLog[ipLogHead];e={};e.ms=millis();e.remoteIp=remote;e.remotePort=port;e.source=cemi.sourceAddress();e.destination=cemi.destinationAddress();e.group=cemi.addressType()==GroupAddress;e.hop=cemi.hopCount();e.apci=cemi.apdu().type();e.rawLen=min(rawLen,kLogRawBytes);e.truncated=rawLen>kLogRawBytes;memcpy(e.raw,raw,e.rawLen);const size_t add=raw[1],apduOffset=add+9,apduLength=size_t(raw[add+8])+1;if(apduOffset+apduLength<=rawLen){e.apduLen=min(apduLength,sizeof(e.apdu));memcpy(e.apdu,raw+apduOffset,e.apduLen);}ipLogHead=(ipLogHead+1)%kLogEntries;}
void routeDecision(const char* format,...){RouteDecision& e=routeDecisions[routeDecisionHead];e.ms=millis();va_list args;va_start(args,format);vsnprintf(e.text,sizeof(e.text),format,args);va_end(args);routeDecisionHead=(routeDecisionHead+1)%kRouteDecisionEntries;if(routeDecisionCount<kRouteDecisionEntries)++routeDecisionCount;}
void clearRouteQueue(){routeHead=routeCount=0;routeActive={};routePair=routeEchoPos=0;}
uint32_t routeHash(const uint8_t* data,size_t len){uint32_t h=2166136261UL;for(size_t i=0;i<len;++i){h^=data[i];h*=16777619UL;}return h;}
bool individualTopologyAllows(bool ipToTp,uint16_t destination){if(!config.paSet||(config.pa&255)!=0)return false;const uint8_t routerArea=config.pa>>12,routerLine=(config.pa>>8)&15,destinationArea=destination>>12,destinationLine=(destination>>8)&15;const bool below=routerLine?destinationArea==routerArea&&destinationLine==routerLine:destinationArea==routerArea;return ipToTp?below:!below;}
bool routeFilterAllows(const CemiFrame& cemi,bool ipToTp,const char*& reason){const routing_policy::Direction& direction=ipToTp?routingPolicy.ipToTp:routingPolicy.tpToIp;if(cemi.addressType()==GroupAddress){if(cemi.destinationAddress()==0){if(!direction.broadcast){reason="broadcast bloque";return false;}}else if(!routing_policy::groupAllowed(routingPolicy,direction,cemi.destinationAddress())){reason=direction.groups==routing_policy::GroupMode::Block?"groupes bloqués":"groupe absent de la table";return false;}}else{if(direction.individuals==routing_policy::IndividualMode::Block){reason="individuelles bloquées";return false;}if(!individualTopologyAllows(ipToTp,cemi.destinationAddress())){reason="individuelle hors topologie locale";return false;}}reason="accepte";return true;}
void rememberFingerprint(RouteFingerprint* list,uint8_t& pos,const CemiFrame& cemi,const uint8_t* raw,size_t len){RouteFingerprint& f=list[pos++%8];f.expiresMs=millis()+kRouteFingerprintTtlMs;f.hash=routeHash(raw,len);f.source=cemi.sourceAddress();f.destination=cemi.destinationAddress();f.hop=cemi.hopCount();f.group=cemi.addressType()==GroupAddress;}
