 if(remote==knxNetworkLocalAddress()||consumeFingerprint(recentIpTx,cemi,cemi.data(),cemi.dataLength())){++routeOwnIpSuppressed;++routeFiltered;routeDecision("echo IP propre supprime: %s -> %s",src,dst);return;}
