 if(!cemi.hopCount()||(config.paSet&&cemi.sourceAddress()==config.pa)||cemi.sourceAddress()==0xFFFF){++routeFiltered;++routeHopRejected;routeDecision("filtre hop/source invalide: %s -> %s hop=%u",src,dst,cemi.hopCount());return;}
