 uint8_t handled=0;UdpRxEvent event;for(;handled<kUdpConsumerMaxBatch&&xQueueReceive(udpRxQueue,&event,0)==pdTRUE;++handled)processIpDatagram(event.data,event.len,IPAddress(event.remote),event.port);if(handled>udpDiagMaxDrained)udpDiagMaxDrained=handled;knx_intersite::TpEvent l3Event;uint8_t l3Handled=0;while(l3Handled<4&&intersiteTransport.receiveRemote(l3Event)){enqueueIntersiteToTp(l3Event.data,l3Event.length);++l3Handled;}
