void formatDuration(uint32_t milliseconds,char* out,size_t capacity){const uint32_t seconds=milliseconds/1000U,hours=seconds/3600U,minutes=(seconds/60U)%60U,remainder=seconds%60U;if(hours)snprintf(out,capacity,"%lu h %02lu min %02lu s",hours,minutes,remainder);else if(minutes)snprintf(out,capacity,"%lu min %02lu s",minutes,remainder);else snprintf(out,capacity,"%lu s",remainder);}
const char* busOperationalState(Diag state){if(kTp1Simulated)return state==Diag::TunnelNormal?"TP1 SIMULATED - tunnel logiciel":"TP1 SIMULATED - aucune liaison physique";switch(state){case Diag::BusMonitor:return "Opérationnel - écoute passive";case Diag::TunnelNormal:return "Opérationnel - mode normal";case Diag::Running:case Diag::ResetReceived:return "Initialisation en cours";case Diag::ProtocolError:return "Défaut de protocole";case Diag::Absent:return "TP1 NON CONNECTÉ - NCN5130 absent";case Diag::Idle:return "Initialisation non lancée";}return "Etat inconnu";}
