 metric(r,"Réseau",v);metric(r,"Erreurs actives",activeError);metric(r,"Période des compteurs",duration);r.write("</div><p><a href='/knx-config'>Configurer KNX</a> &middot; <a href='/knx-advanced'>Diagnostic avancé</a> &middot; <a href='/knx-help'>Aide installateur</a></p></section>");
