void diagnosticPost(WebRequest& q,WebResponse& r,void*){
 String action=q.hasArg("action")?q.arg("action"):"diagnostic";
 if(!KNX_DEVELOPMENT_TOOLS&&(action=="tp_off"||action=="tp_on"||action=="uart_sweep"||action=="uart_loopback"||action=="uart_invert_toggle")){r.sendText("Outil de banc absent du firmware installateur",404);return;}
 if(action=="maintenance_reset"){if(!q.hasArg("confirm")){r.sendText("Confirmation de maintenance requise",400);return;}if(tunnel.enabled||ipTpEnabled){r.sendText("Arreter d'abord les tunnels et le routage; aucune session n'a ete interrompue",409);return;}if(!enqueueNcnRestart(true)){r.sendText("File de commandes NCN5130 pleine",503);return;}r.sendText("Reinitialisation NCN5130 mise en file; retour en ecoute passive attendu.",202);return;}
 if(action=="udp_diag_reset"){resetUdpDiag();r.sendText("Diagnostic UDP remis a zero; routage inchange et passif.");return;}
 if(action=="tunnel_enable"){if(tunnel.enabled){r.sendText("Tunnel deja actif",409);return;}if(diag!=Diag::BusMonitor&&diag!=Diag::TunnelNormal){r.sendText("Activation refusee : NCN5130 hors etat stable",409);return;}nodeRedTunnelMode=false;for(uint8_t i=0;i<kTunnelSlots;++i)tunnels[i].address=config.tunnelAddresses[i];closeManagement("Aucune session");closeAllTunnels("Emplacement libre",false);tunnel.enabled=true;if(diag==Diag::TunnelNormal){tunnel.ready=true;strlcpy(tunnel.last,"Serveur actif; mode normal partage avec routage",sizeof(tunnel.last));r.sendText("Serveur cinq tunnels configure; emplacements sans adresse indisponibles.");return;}NcnCommand command;command.type=NcnCommandType::EnterTunnel;command.clearLogs=false;if(!enqueueNcnCommand(command)){tunnel.enabled=false;r.sendText("File NCN5130 pleine",503);return;}tunnel.ready=false;strlcpy(tunnel.last,"Activation demandee; initialisation mode normal",sizeof(tunnel.last));r.sendText("Serveur cinq tunnels configure; attente du mode normal NCN5130.",202);return;}
 if(action=="node_red_tunnel_enable"){if(tunnel.enabled){r.sendText("Tunnel deja actif",409);return;}if(!siemensDisconnectedConfirmed){r.sendText("Activation refusee : confirmer d'abord l'absence de chemin IP/TP parallele",423);return;}if(!activateNodeRedTunnel("Profil Node-RED demande; attente mode normal")){r.sendText("Activation refusee : routage actif, NCN5130 hors Busmon ou file pleine",409);return;}if(!saveNodeRedAutoRestore(true)){tunnel.enabled=false;closeAllTunnels("Persistance Node-RED impossible",true);nodeRedTunnelMode=false;r.sendText("Activation annulee : echec enregistrement NVS",500);return;}r.sendText("Profil Node-RED TunnelUDP configure actif et restaure apres redemarrage.",202);return;}
 if(action=="tunnel_disable"){if(!saveNodeRedAutoRestore(false)){r.sendText("Desactivation refusee : echec enregistrement NVS",500);return;}nodeRedRestorePending=false;tunnel.enabled=false;closeManagement("Session de gestion liberee; serveur desactive");closeAllTunnels("Tunnel desactive",!ipTpEnabled);nodeRedTunnelMode=false;siemensDisconnectedConfirmed=false;r.sendText(ipTpEnabled?"Tunnels desactives; mode normal conserve pour le routage.":"Tunnels et gestion desactives; retour Busmon demande.");return;}
 if(action=="routing_confirm_disconnected"){if(ipTpEnabled){r.sendText("Desactiver d'abord le routage",409);return;}siemensDisconnectedConfirmed=true;clearRouteQueue();routeDecision("absence de chemin de routage parallele confirmee pour cette session");r.sendText("Absence de chemin parallele confirmee pour cette session. Le routage reste passif.");return;}
 if(action=="routing_enable"){if(!ROUTING_ARMED){r.sendText("Activation refusee : ROUTING_ARMED=0, firmware strictement passif",423);return;}if(ipTpEnabled){r.sendText("Routage deja actif",409);return;}if(!siemensDisconnectedConfirmed){r.sendText("Activation refusee : confirmer d'abord l'absence de double chemin",423);return;}if(diag!=Diag::BusMonitor&&diag!=Diag::TunnelNormal){r.sendText("Activation refusee : NCN5130 hors etat stable",409);return;}if(!enableIpToTp()){r.sendText("Activation refusee : sens non configure ou file indisponible",423);return;}r.sendText("Initialisation du moteur bidirectionnel lancee selon la configuration persistante.",202);return;}
 if(action=="routing_disable"){disableIpToTp("commande Web");r.sendText("Mode passif restaure; files supprimees et aucun rejeu.");return;}
 if(action=="routing_clear"){routeDecisionHead=routeDecisionCount=0;r.sendText("Journal des decisions efface; file et mode inchanges.");return;}
 if(ipTpPhase!=IpTpPhase::Passive&&(action=="diagnostic"||action=="reset_diagnostics"||action=="uart_sweep"||action=="uart_loopback"||action=="uart_invert_toggle")){r.sendText("UART2 appartient au routage IP vers TP; revenir d'abord au mode passif",409);return;}
#if KNX_DEVELOPMENT_TOOLS
 if(action=="tp_off"||action=="tp_on"){if(!TP_TEST_ARMED){r.sendText("Essai TP verrouille par TP_TEST_ARMED=0",423);return;}if(tpTest.phase==TpTestPhase::ResetWait||tpTest.phase==TpTestPhase::StateWait||tpTest.phase==TpTestPhase::ConfirmWait){r.sendText("Essai TP deja en cours",409);return;}if(diag!=Diag::BusMonitor){r.sendText("Bus monitor NCN5130 non actif; emission refusee",409);return;}startTpTest(action=="tp_on");r.sendText(action=="tp_on"?"Une demande ON de developpement est lancee.":"Une demande OFF de developpement est lancee.",202);return;}
#endif
 if(action=="listen_stop"){leaveMulticast();r.sendText("Arret d'ecoute demande a la tache UDP; routage toujours desactive.");return;}if(action=="listen_start"){joinMulticast();r.sendText("Ecoute demandee a la tache UDP; inscription a la prochaine connexion Wi-Fi.",202);return;}if(action=="display_toggle"){ipDisplayPaused=!ipDisplayPaused;r.sendText(ipDisplayPaused?"Journal fige; la reception et les compteurs continuent.":"Journal repris.");return;}if(action=="clear_log"){ipLogHead=ipLogCount=0;r.sendText("Journal KNXnet/IP efface.");return;}if(action=="diagnostic"||action=="reset_diagnostics"){if(!enqueueNcnRestart(true)){r.sendText("File de commandes NCN5130 pleine",503);return;}r.sendText("Reinitialisation NCN5130 mise en file pour la tache UART; aucun acces UART depuis le Web.",202);return;}if(action=="uart_sweep"||action=="uart_loopback"||action=="uart_invert_toggle"){r.sendText("Outil suspendu dans le mode UART a proprietaire unique",423);return;}r.sendText("Action inconnue",400);
}

void commissioningPage(WebResponse& r,void*){char address[24]="Configuration requise",v[96];if(config.paSet)formatPa(config.pa,address,sizeof(address));r.beginPage("KNX - Mise en service");r.write("<section class='card'><h2>Etat</h2><div class='metrics'>");metric(r,"Adresse routeur",address);snprintf(v,sizeof(v),"%u / %u",configuredTunnelCount(config),unsigned(kTunnelSlots));metric(r,"Adresses tunnel configurees",v);metric(r,"Activation",commissioningReady(config)?"Configuration utilisable":"CONFIGURATION REQUISE");r.write("</div><p>La saisie manuelle se fait dans <a href='/knx-config'>KNX - Config</a>. Reserver toutes les adresses dans ETS.</p></section><section class='card'><h2>Attribution automatique assistee</h2><p>Une absence de reponse ne garantit pas qu'une adresse est libre : un appareil peut etre hors tension.</p><form method='post' action='/knx-auto-address'><label>Zone<input name='area' type='number' min='0' max='15' required></label><label>Ligne<input name='line' type='number' min='0' max='15' required></label><label>Premier appareil<input name='start' type='number' min='1' max='255' required></label><label>Dernier appareil<input name='end' type='number' min='1' max='255' required></label><button type='submit'>Preparer l'analyse explicite</button></form><p class='muted'>Le scan TP autonome n'est pas implemente. Le bouton valide seulement la plage, sans emission ni enregistrement.</p></section>");r.endPage();}
void commissioningPost(WebRequest& q,WebResponse& r,void*){for(const char* name:{"area","line","start","end"})if(!q.hasArg(name)){r.sendText("Parametres manquants; aucun scan effectue",400);return;}uint32_t area,line,start,end;if(!parseUInt(q.arg("area").c_str(),0,15,area)||!parseUInt(q.arg("line").c_str(),0,15,line)||!parseUInt(q.arg("start").c_str(),1,255,start)||!parseUInt(q.arg("end").c_str(),1,255,end)||start>end||end-start+1<kTunnelSlots){r.sendText("Plage invalide ou trop courte; aucun scan effectue",400);return;}char message[256];snprintf(message,sizeof(message),"Plage %lu.%lu.%lu a %lu.%lu.%lu validee, mais scan TP non implemente : aucune emission et aucun enregistrement. Reserver les futures adresses dans ETS.",area,line,start,area,line,end);r.sendText(message,501);}

void helpPage(WebResponse& r,void*){r.beginPage("KNX - Aide installateur");r.write("<section class='card'><h2>Premiere mise en service</h2><ol><li>Configurer le Wi-Fi depuis ESP_BASE.</li><li>Attribuer une adresse x.y.0 au routeur si le routage individuel topologique est nécessaire.</li><li>Reserver dans ETS des adresses distinctes pour les tunnels; laisser vide tout emplacement inutilise.</li><li>Enregistrer, verifier le bus puis activer uniquement le service voulu.</li></ol><p>Aucune adresse KNX n'est attribuee automatiquement au demarrage.</p></section><section class='card'><h2>Tunneling et routing</h2><p>Le tunneling est une connexion unicast pour ETS ou Node-RED. Le routing transporte des ROUTING_INDICATION multicast entre IP et TP. Les filtres de routing n'affectent jamais les tunnels.</p><p>Le routing demarre toujours passif. Le profil tunnel persistant, s'il a ete explicitement active, est restaure séparément.</p></section><section class='card'><h2>Filtrage</h2><p>Chaque sens peut bloquer, tout transmettre ou filtrer les groupes avec la table commune. La table n'agit qu'en mode <em>Filtrer par table</em>. Une table vide n'autorise aucun groupe. <code>0/0/0-31/7/255</code> autorise tout l'espace groupe.</p><p>Le mode individuel topologique exige une adresse routeur x.y.0.</p></section><section class='card'><h2>Sauvegarde et restauration</h2><p>L'enregistrement ne demarre pas le routing. KXRF1 decrit seulement la table commune. L'import est limite a 12 288 octets et une erreur laisse la configuration NVS effective inchangee.</p></section><section class='card'><h2>Etats et depannage</h2><p><strong>Opérationnel - écoute passive</strong> signifie que le bus est surveille sans routing. <strong>Mode normal</strong> permet tunneling ou routing. <strong>Libre</strong> designe un tunnel configure sans client; <strong>Non configuré</strong>, un emplacement sans adresse.</p><p>Verifier Wi-Fi, alimentation KNX, etat NCN5130, reservation des adresses et absence de chemin IP/TP parallele. Le diagnostic avance separe UDP brut, tunneling, routing et messages ignorés.</p><p>Cette reference n'est pas certifiee KNX. Le routage multicast complet reste partiellement valide. Le Web et l'OTA ne sont pas authentifies : utiliser un reseau de confiance.</p><p><a href='/knx'>Etat</a> &middot; <a href='/knx-config'>Configuration</a></p></section>");r.endPage();}
void maintenancePage(WebResponse& r,void*){r.beginPage("KNX - Maintenance");r.write("<section class='card'><h2>Maintenance NCN5130</h2><p>Le diagnostic local ferme et reouvre UART2, envoie U_Reset puis U_State et revient en ecoute passive si les reponses sont valides.</p><p><strong>Effet :</strong> toute session tunnel doit etre arretee avant l'operation. L'ouverture de cette page ne lance aucune commande.</p><form method='post' action='/knx-diagnostic'><input type='hidden' name='action' value='maintenance_reset'><label><input type='checkbox' name='confirm' value='1' required style='width:auto'> Je confirme l'interruption de maintenance</label><button type='submit'>Reinitialiser le transceiver</button></form><p class='muted'>Les outils de boucle, balayage, inversion et commandes de groupe fixes ne sont pas inclus dans ce firmware installateur.</p><p><a href='/knx-advanced'>Retour au diagnostic avance</a></p></section>");r.endPage();}
void knxPage(WebRequest& q,WebResponse& r,void*){const String view=q.arg("view");if(view=="advanced")advancedPage(r,nullptr);else if(view=="maintenance")maintenancePage(r,nullptr);else if(view=="help")helpPage(r,nullptr);else statePage(r,nullptr);}

void writeModeOptions(WebResponse& r,routing_policy::GroupMode selected){for(auto mode:{routing_policy::GroupMode::Block,routing_policy::GroupMode::RouteAll,routing_policy::GroupMode::Filter}){r.write("<option value='");r.write(routing_policy::groupModeName(mode));r.write("'");if(mode==selected)r.write(" selected");r.write(">");r.write(mode==routing_policy::GroupMode::Block?"Bloquer":mode==routing_policy::GroupMode::RouteAll?"Transmettre tout":"Filtrer par table");r.write("</option>");}}
size_t serializedRangesLength(const routing_policy::Model& policy){size_t total=0;bool firstOutput=true;for(uint32_t address=0;address<routing_policy::kAddressCount;){if(!routing_policy::contains(policy,uint16_t(address))){++address;continue;}uint16_t first=uint16_t(address),last=first;while(address+1<routing_policy::kAddressCount&&routing_policy::contains(policy,uint16_t(address+1)))last=uint16_t(++address);char a[16],b[16];routing_policy::formatGroup(first,a,sizeof(a));routing_policy::formatGroup(last,b,sizeof(b));total+=(firstOutput?0:2)+strlen(a)+(last==first?0:1+strlen(b));firstOutput=false;++address;}return total;}
bool writeRanges(WebResponse& r,const routing_policy::Model& policy){if(serializedRangesLength(policy)>routing_policy::kMaxImportBytes)return false;bool firstOutput=true;for(uint32_t address=0;address<routing_policy::kAddressCount;){if(!routing_policy::contains(policy,uint16_t(address))){++address;continue;}uint16_t first=uint16_t(address),last=first;while(address+1<routing_policy::kAddressCount&&routing_policy::contains(policy,uint16_t(address+1)))last=uint16_t(++address);char a[16],b[16];routing_policy::formatGroup(first,a,sizeof(a));routing_policy::formatGroup(last,b,sizeof(b));if(!firstOutput)r.write(", ");r.write(a);if(last!=first){r.write("-");r.write(b);}firstOutput=false;++address;}return true;}
