 char pa[16]="",mc[20],number[24];if(config.paSet)formatPa(config.pa,pa,sizeof(pa));formatIp(config.multicast,mc,sizeof(mc));uint32_t allowed=0;for(size_t i=0;i<routing_policy::kBitmapBytes;++i)allowed+=__builtin_popcount(unsigned(routingPolicy.groups[i]));
 r.beginPage("KNX - Configuration installateur");r.write(kInstallerStyle);r.write("<section class='card'><h2>État et activation</h2><div class='metrics installer-metrics'>");metric(r,"Capacité",ROUTING_ARMED?"Disponible":"Verrouillée dans ce firmware");metric(r,"Configuration enregistrée",commissioningReady(config)?"Prête":"Configuration requise");metric(r,"Fonctionnement actuel",ipTpEnabled?"Routage actif":"Routage passif");metric(r,"Tunnels",tunnel.enabled?"Serveur actif":"Serveur inactif");r.write("</div><p>L'enregistrement n'active jamais le routage. Après redémarrage, le routage reste passif; le profil tunnel persistant est restaure séparément.</p><form method='post' action='/knx-diagnostic'><input type='hidden' name='action' value='routing_confirm_disconnected'><button type='submit'>Confirmer l'absence de chemin de routage parallele</button></form><form method='post' action='/knx-diagnostic'><input type='hidden' name='action' value='routing_enable'><button type='submit'>Activer le routage configure</button></form><form method='post' action='/knx-diagnostic'><input type='hidden' name='action' value='routing_disable'><button type='submit'>Desactiver le routage</button></form></section>");
 r.write("<form method='post' action='/knx-config-save'><section class='card'><h2>Identité KNX</h2><label>Adresse individuelle du routeur<input name='physical_address' maxlength='10' placeholder='2.1.0' value='");if(pa[0])r.write(pa);r.write("'></label><p class='muted'>Une adresse x.y.0 est nécessaire uniquement pour le routage individuel topologique. Aucune adresse existante n'est modifiée automatiquement.</p></section><section class='card'><h2>Connexions ETS et logiciels</h2><p>Cinq adresses distinctes, réservées dans ETS. Un champ vide rend l'emplacement indisponible.</p>");for(uint8_t slot=0;slot<kTunnelSlots;++slot){char address[16]="",label[96];if(config.tunnelAddresses[slot])formatPa(config.tunnelAddresses[slot],address,sizeof(address));snprintf(label,sizeof(label),"<label>Emplacement %u<input name='tunnel_%u' maxlength='10' placeholder='Non configuré' value='",unsigned(slot+1),unsigned(slot+1));r.write(label);if(address[0])r.write(address);r.write("'></label>");}r.write("<p class='muted'>Le filtrage du routing ne s'applique pas aux tunnels.</p></section>");
 r.write("<section class='card'><h2>Routage IP vers TP</h2><label><input name='route_ip_tp' type='checkbox' value='1' style='width:auto'");if(config.routeIpToTp)r.write(" checked");r.write("> Activer cette direction</label><label>Télégrammes de groupe<select name='ip_group_mode'>");writeModeOptions(r,routingPolicy.ipToTp.groups);r.write("</select></label><label><input name='ip_individual' type='checkbox' value='1' style='width:auto'");if(routingPolicy.ipToTp.individuals==routing_policy::IndividualMode::Topology)r.write(" checked");r.write("> Individuelles selon la topologie (sinon bloquées)</label><label><input name='ip_broadcast' type='checkbox' value='1' style='width:auto'");if(routingPolicy.ipToTp.broadcast)r.write(" checked");r.write("> Transmettre les broadcasts (sinon bloqués)</label></section><section class='card'><h2>Routage TP vers IP</h2><label><input name='route_tp_ip' type='checkbox' value='1' style='width:auto'");if(config.routeTpToIp)r.write(" checked");r.write("> Activer cette direction</label><label>Télégrammes de groupe<select name='tp_group_mode'>");writeModeOptions(r,routingPolicy.tpToIp.groups);r.write("</select></label><label><input name='tp_individual' type='checkbox' value='1' style='width:auto'");if(routingPolicy.tpToIp.individuals==routing_policy::IndividualMode::Topology)r.write(" checked");r.write("> Individuelles selon la topologie (sinon bloquées)</label><label><input name='tp_broadcast' type='checkbox' value='1' style='width:auto'");if(routingPolicy.tpToIp.broadcast)r.write(" checked");r.write("> Transmettre les broadcasts (sinon bloqués)</label></section>");
 snprintf(number,sizeof(number),"%lu",allowed);r.write("<section class='card'><h2>Table commune de groupes autorises</h2><div class='metrics'>");metric(r,"Groupes autorises",number);r.write("</div><p>Cette table n'agit que lorsque la direction utilise <em>Filtrer par table</em>. Table vide = aucun groupe. <code>0/0/0-31/7/255</code> = tous les groupes.</p><label>Import KXRF1 ou liste d'adresses/plages<textarea name='group_ranges' rows='7' maxlength='12288' placeholder='KXRF1: 0/0/1, 1/0/0-1/7/255'>");if(!writeRanges(r,routingPolicy))r.write("EXPORT_TROP_VOLUMINEUX");r.write("</textarea></label><p class='muted'>Import limite a 12 288 octets. En cas d'erreur, la configuration enregistree reste intacte; utiliser Retour dans le navigateur pour conserver la saisie.</p><details><summary>Aide technique bitmap</summary><p>Bitmap commun de 8 192 octets couvrant les 65 536 adresses de groupe.</p></details></section>");
 r.write("<section class='card'><details><summary>Paramètres réseau KNX/IP avancés</summary><label>Groupe multicast<input name='multicast' required value='");r.write(mc);snprintf(number,sizeof(number),"%u",config.port);r.write("'></label><label>Port UDP<input name='port' type='number' min='1' max='65535' value='");r.write(number);snprintf(number,sizeof(number),"%lu",config.timeoutMs);r.write("'></label><input type='hidden' name='diag_timeout' value='");r.write(number);snprintf(number,sizeof(number),"%lu",config.probeMs);r.write("'><input type='hidden' name='probe_interval' value='");r.write(number);r.write("'></details></section><section class='card'><h2>Sauvegarde</h2><button type='submit'>Enregistrer la configuration</button><p><a href='/knx-help'>Consulter l'aide installateur</a></p></section></form><section class='card'><h2>Export KXRF1 et maintenance</h2><p><strong>Export KXRF1 :</strong> <code>KXRF1: ");if(!writeRanges(r,routingPolicy))r.write("EXPORT_TROP_VOLUMINEUX");r.write("</code></p><form method='post' action='/knx-config-save'><input type='hidden' name='routing_defaults' value='1'><button type='submit'>Restaurer les politiques de routage passives</button></form><p class='muted'>Les adresses du routeur et des tunnels sont préservées.</p></section>");r.endPage();
